    title: r'''La leyenda de Zelma''',
    meme: r'''el triángulo del poder gatuno''',
    file: r'''zelma''',
    sig:
        r'''int poder_maximo(std::vector<std::vector<int>> sueltos, std::vector<int> centro);''',
    statement:
        r'''Hay 3 fragmentos triangulares sueltos y uno central fijo (se puede rotar, no mover). Los sueltos van en las ranuras A, B, C, en cualquier orden, y cada uno se puede rotar (desplazar sus 3 valores en círculo, sin voltearlo).

Fragmento en ranura A = (a, b, c), B = (d, e, f), C = (g, h, i), centro = (x, y, z).
Uniones: b = d = y, f = h = z, c = g = x. Poder = a + e + i.

Implementá poder_maximo(sueltos, centro): el poder máximo de un armado válido, o IMPOSIBLE (−1000000) si no existe.

Ejemplo: poder_maximo([[8,3,10],[5,15,3],[20,5,8]], [5,3,8]) = 45.

Restricción: cada valor entre −1000 y 1000.''',
    header: r'''#ifndef ZELMA_H
#define ZELMA_H

#include <vector>

// Value to return when no valid assembly exists.
const int IMPOSIBLE = -1000000;

// sueltos: the 3 loose fragments, each with its 3 values in clockwise order,
//          as placed in a slot without rotating it: bottom-left, top, bottom-right tip.
// centro:  the anchored central fragment x, y, z: bottom, top-left, top-right tip.
// Returns the maximum power, or IMPOSIBLE if no valid assembly exists.
int poder_maximo(std::vector<std::vector<int>> sueltos, std::vector<int> centro);

#endif
''',
    grader: r'''#include <cstdio>
#include <vector>
#include "zelma.h"

int main()
{
    std::vector<std::vector<int>> sueltos(3, std::vector<int>(3));
    std::vector<int> centro(3);
    for (int i = 0; i < 3; i++)
        for (int j = 0; j < 3; j++)
            if (scanf("%d", &sueltos[i][j]) != 1) return 1;
    for (int j = 0; j < 3; j++)
        if (scanf("%d", &centro[j]) != 1) return 1;
    int res = poder_maximo(sueltos, centro);
    if (res == IMPOSIBLE) printf("IMPOSIBLE\n");
    else printf("%d\n", res);
    return 0;
}
''',
    batch: r'''#include <cstdio>
#include <vector>
int main(){int T;if(scanf("%d",&T)!=1)return 1;while(T--){std::vector<std::vector<int>> s(3,std::vector<int>(3));std::vector<int> c(3);for(int i=0;i<3;i++)for(int j=0;j<3;j++)scanf("%d",&s[i][j]);for(int j=0;j<3;j++)scanf("%d",&c[j]);int r=poder_maximo(s,c);if(r==IMPOSIBLE)printf("IMPOSIBLE\n");else printf("%d\n",r);}return 0;}
''',
